edits.new:
/* Each B panel contains 512 K slices of 32 adjacent columns. */
float *packed_b = malloc((size_t)512 * 512 * sizeof(float));
if (!packed_b) {
    fallback_gemm(n, A, B, C);
    return;
}
for (int panel = 0; panel < 16; ++panel) {
    for (int k = 0; k < 512; ++k) {
        const float *src = B + (size_t)k * 512 + panel * 32;
        float *dst = packed_b + (size_t)panel * 16384 + k * 32;
        for (int column = 0; column < 32; ++column) {
            dst[column] = src[column];
        }
    }
}
/* Preserve C^T=B^T*A^T operand roles. The adapted B consumer reads
   packed panels; parameter offsets retain the pinned LIBXSMM ABI. */
const void *parameters[22] = {0};
parameters[4] = packed_b;
parameters[10] = A;
parameters[16] = C;
sera_libxsmm_512(parameters);
free(packed_b);
